#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    struct PieceData {
        int k;
        vector<pair<int,int>> cells;
    };
    vector<PieceData> pieces(n);
    int totalCells = 0;
    for(int i=0;i<n;i++){
        cin >> pieces[i].k;
        pieces[i].cells.resize(pieces[i].k);
        for(int j=0;j<pieces[i].k;j++){
            cin >> pieces[i].cells[j].first >> pieces[i].cells[j].second;
        }
        totalCells += pieces[i].k;
    }

    // Precompute orientations for each piece
    struct OriInfo {
        vector<pair<int,int>> cells; // normalized
        int w, h;
        int f, r;
    };

    vector<vector<OriInfo>> allOris(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++){
            for(int r=0;r<4;r++){
                vector<pair<int,int>> tc;
                for(auto [x,y]: pieces[i].cells){
                    int nx=x, ny=y;
                    if(f) nx=-nx;
                    for(int q=0;q<r;q++){
                        int tmp=nx; nx=ny; ny=-tmp;
                    }
                    tc.push_back({nx,ny});
                }
                int minx=INT_MAX, miny=INT_MAX;
                for(auto [x,y]:tc){minx=min(minx,x);miny=min(miny,y);}
                for(auto&[x,y]:tc){x-=minx;y-=miny;}
                sort(tc.begin(),tc.end());
                if(seen.insert(tc).second){
                    int w=0,h=0;
                    for(auto[x,y]:tc){w=max(w,x+1);h=max(h,y+1);}
                    allOris[i].push_back({tc,w,h,f,r});
                }
            }
        }
    }

    // Sort pieces: largest first
    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a, int b){
        return pieces[a].k > pieces[b].k;
    });

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]()->double{
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    double sqrtArea = sqrt((double)totalCells * 1.05);

    // Try a few candidate widths
    vector<int> candidateW;
    for(double mult=0.7; mult<=2.5; mult+=0.15){
        int w = max(10, (int)(sqrtArea*mult));
        candidateW.push_back(w);
    }
    sort(candidateW.begin(),candidateW.end());
    candidateW.erase(unique(candidateW.begin(),candidateW.end()),candidateW.end());

    long long bestArea = (long long)1e18;
    int bestH=0, bestW=0;

    struct Placement { int x,y,r,f; };
    vector<Placement> bestPlacements(n);

    for(int W : candidateW){
        if(elapsed()>8.5) break;

        int maxPossH = (totalCells + W - 1)/W + 20;
        // cap maxPossH reasonably
        maxPossH = min(maxPossH, totalCells + 100);

        // Use a flat grid
        int gridH = maxPossH;
        vector<vector<bool>> grid(W, vector<bool>(gridH, false));
        vector<int> heightmap(W, 0);

        vector<Placement> placements(n);
        int maxY = 0;
        bool failed = false;

        for(int idx=0; idx<n && !failed; idx++){
            int pi = order[idx];
            int bestScore = INT_MAX;
            int bx=-1, by_=-1, br=-1, bf=-1;

            for(auto& ori : allOris[pi]){
                if(ori.w > W) continue;

                for(int x=0; x<=W-ori.w; x++){
                    // heightmap lower bound
                    int minY=0;
                    for(auto[cx,cy]:ori.cells){
                        int needed = heightmap[x+cx]-cy;
                        if(needed>minY) minY=needed;
                    }
                    if(minY<0) minY=0;

                    // scan upward
                    for(int y=minY; ; y++){
                        int topY=0;
                        bool ok=true;
                        for(auto[cx,cy]:ori.cells){
                            int py=y+cy;
                            if(py>=gridH){ok=false;break;}
                            if(grid[x+cx][py]){ok=false;break;}
                            if(py+1>topY) topY=py+1;
                        }
                        if(!ok){
                            if(y>minY+5) break; // don't scan too far
                            continue;
                        }
                        int score = topY*10000 + y*10 + x;
                        if(score < bestScore){
                            bestScore=score;
                            bx=x; by_=y; br=ori.r; bf=ori.f;
                        }
                        break; // found lowest y for this x
                    }
                }
            }

            if(bx==-1){failed=true;break;}

            // find the matching ori to place
            for(auto& ori : allOris[pi]){
                if(ori.r==br && ori.f==bf && ori.w<=W){
                    for(auto[cx,cy]:ori.cells){
                        int px=bx+cx, py=by_+cy;
                        grid[px][py]=true;
                        if(py+1>heightmap[px]) heightmap[px]=py+1;
                        if(py+1>maxY) maxY=py+1;
                    }
                    break;
                }
            }

            placements[pi]={bx,by_,br,bf};
        }

        if(failed) continue;

        long long area = (long long)W * maxY;
        if(area < bestArea || (area==bestArea && (maxY<bestH || (maxY==bestH && W<bestW)))){
            bestArea=area;
            bestH=maxY;
            bestW=W;
            bestPlacements=placements;
        }
    }

    if(bestArea >= (long long)1e18){
        // fallback: single row
        bestW = totalCells;
        bestH = 10;
        // just place trivially... (shouldn't happen)
    }

    cout << bestW << " " << bestH << "\n";
    for(int i=0;i<n;i++){
        cout << bestPlacements[i].x << " " << bestPlacements[i].y << " "
             << bestPlacements[i].r << " " << bestPlacements[i].f << "\n";
    }

    return 0;
}
